/**
 * ApiForge Lite - Spring Boot OpenAPI 3.x Parser Engine (Step 7)
 * 
 * Safely parses OpenAPI 3.0.x and 3.1.x specifications generated by Spring Boot / springdoc-openapi.
 * Handles local $ref resolution with circular reference detection, parameter extraction,
 * schema-driven request body generation, and conversion to ApiForge request models.
 */

const SUPPORTED_HTTP_METHODS = ['get', 'post', 'put', 'patch', 'delete', 'head', 'options'];
const MAX_DOC_SIZE_BYTES = 10 * 1024 * 1024; // 10 MB limit
const MAX_RECURSION_DEPTH = 6;

/**
 * Validates the raw OpenAPI document structure and version.
 * @param {any} doc 
 */
function validateOpenApiDocument(doc) {
  if (!doc || typeof doc !== 'object' || Array.isArray(doc)) {
    throw new Error('Invalid OpenAPI document: Expected a JSON object root.');
  }

  // Detect Swagger 2.0
  if (doc.swagger && typeof doc.swagger === 'string') {
    throw new Error(`Swagger 2.0 (version ${doc.swagger}) is not supported. Please provide an OpenAPI 3.x document.`);
  }

  // Enforce OpenAPI 3.x
  if (!doc.openapi || typeof doc.openapi !== 'string') {
    throw new Error('Missing "openapi" version string in specification document.');
  }

  const trimmedVersion = doc.openapi.trim();
  if (!trimmedVersion.startsWith('3.')) {
    throw new Error(`Unsupported OpenAPI version "${doc.openapi}". Only OpenAPI 3.x documents are supported.`);
  }

  if (!doc.paths || typeof doc.paths !== 'object') {
    throw new Error('OpenAPI document must contain a "paths" object.');
  }
}

/**
 * Resolves a local JSON pointer (e.g. #/components/schemas/User) within the document.
 * Safely ignores external URLs or files and guards against circular references.
 * 
 * @param {object} doc 
 * @param {string} ref 
 * @param {Set<string>} seenRefs 
 * @returns {any}
 */
function resolveLocalRef(doc, ref, seenRefs = new Set()) {
  if (!ref || typeof ref !== 'string') return null;

  // External references are not fetched in this step
  if (ref.startsWith('http://') || ref.startsWith('https://') || ref.startsWith('file:')) {
    return null;
  }

  // Only handle local pointers starting with '#/'
  if (!ref.startsWith('#/')) {
    return null;
  }

  if (seenRefs.has(ref)) {
    // Circular reference detected
    return { type: 'object', description: '[Circular Reference]' };
  }

  seenRefs.add(ref);

  const parts = ref.substring(2).split('/').map(decodeURIComponent);
  let current = doc;

  for (const part of parts) {
    if (!current || typeof current !== 'object') {
      return null;
    }
    current = current[part];
  }

  // If the resolved target is itself a reference, recursively resolve it
  if (current && typeof current === 'object' && current.$ref) {
    return resolveLocalRef(doc, current.$ref, seenRefs);
  }

  return current || null;
}

/**
 * Recursively generates a sample JSON value from an OpenAPI schema definition.
 * 
 * @param {object} doc 
 * @param {object} schema 
 * @param {number} depth 
 * @param {Set<string>} seenRefs 
 * @returns {any}
 */
function synthesizeJsonFromSchema(doc, schema, depth = 0, seenRefs = new Set()) {
  if (!schema || typeof schema !== 'object' || depth > MAX_RECURSION_DEPTH) {
    return null;
  }

  // Resolve $ref if present
  if (schema.$ref) {
    if (seenRefs.has(schema.$ref)) {
      return {};
    }
    const resolved = resolveLocalRef(doc, schema.$ref, new Set(seenRefs));
    if (!resolved) return {};
    return synthesizeJsonFromSchema(doc, resolved, depth + 1, seenRefs);
  }

  // 1. Explicit example or default takes precedence
  if (schema.example !== undefined) return schema.example;
  if (schema.default !== undefined) return schema.default;

  // 2. Handle allOf by merging
  if (Array.isArray(schema.allOf)) {
    let merged = {};
    for (const sub of schema.allOf) {
      const subVal = synthesizeJsonFromSchema(doc, sub, depth + 1, seenRefs);
      if (subVal && typeof subVal === 'object') {
        merged = { ...merged, ...subVal };
      }
    }
    return merged;
  }

  // 3. Handle oneOf / anyOf by taking the first option
  if (Array.isArray(schema.oneOf) && schema.oneOf.length > 0) {
    return synthesizeJsonFromSchema(doc, schema.oneOf[0], depth + 1, seenRefs);
  }
  if (Array.isArray(schema.anyOf) && schema.anyOf.length > 0) {
    return synthesizeJsonFromSchema(doc, schema.anyOf[0], depth + 1, seenRefs);
  }

  // 4. Handle based on type
  const type = schema.type || (schema.properties ? 'object' : 'string');

  switch (type) {
    case 'string':
      if (schema.format === 'date-time') return '2026-01-01T12:00:00Z';
      if (schema.format === 'date') return '2026-01-01';
      if (schema.format === 'email') return 'user@example.com';
      if (schema.format === 'uuid') return '3fa85f64-5717-4562-b3fc-2c963f66afa6';
      if (Array.isArray(schema.enum) && schema.enum.length > 0) return schema.enum[0];
      return 'string';

    case 'integer':
      return 0;

    case 'number':
      return 0.0;

    case 'boolean':
      return false;

    case 'array':
      if (schema.items) {
        const itemSample = synthesizeJsonFromSchema(doc, schema.items, depth + 1, seenRefs);
        return itemSample !== null ? [itemSample] : [];
      }
      return [];

    case 'object':
      if (schema.properties && typeof schema.properties === 'object') {
        const obj = {};
        for (const [propName, propSchema] of Object.entries(schema.properties)) {
          obj[propName] = synthesizeJsonFromSchema(doc, propSchema, depth + 1, seenRefs);
        }
        return obj;
      }
      return {};

    default:
      return null;
  }
}

/**
 * Extracts a formatted JSON request body from an OpenAPI operation's requestBody.
 * 
 * @param {object} doc 
 * @param {object} requestBody 
 * @returns {{ body: string, contentType: string }}
 */
function extractRequestBody(doc, requestBody) {
  if (!requestBody || typeof requestBody !== 'object') {
    return { body: '', contentType: 'application/json' };
  }

  let resolvedBody = requestBody;
  if (requestBody.$ref) {
    resolvedBody = resolveLocalRef(doc, requestBody.$ref) || requestBody;
  }

  if (!resolvedBody.content || typeof resolvedBody.content !== 'object') {
    return { body: '', contentType: 'application/json' };
  }

  // Prioritize application/json, application/*+json, then any
  const mediaTypes = Object.keys(resolvedBody.content);
  const jsonType = mediaTypes.find(m => m === 'application/json' || m.includes('+json') || m === '*/*') || mediaTypes[0];

  if (!jsonType) {
    return { body: '', contentType: 'application/json' };
  }

  const mediaObj = resolvedBody.content[jsonType];
  if (!mediaObj) {
    return { body: '', contentType: 'application/json' };
  }

  // 1. Direct example in media object
  if (mediaObj.example !== undefined) {
    return {
      body: JSON.stringify(mediaObj.example, null, 2),
      contentType: jsonType
    };
  }

  // 2. Examples dictionary
  if (mediaObj.examples && typeof mediaObj.examples === 'object') {
    const firstExKey = Object.keys(mediaObj.examples)[0];
    if (firstExKey) {
      let exItem = mediaObj.examples[firstExKey];
      if (exItem && exItem.$ref) {
        exItem = resolveLocalRef(doc, exItem.$ref) || exItem;
      }
      const val = exItem && exItem.value !== undefined ? exItem.value : exItem;
      return {
        body: JSON.stringify(val, null, 2),
        contentType: jsonType
      };
    }
  }

  // 3. Schema synthesis
  if (mediaObj.schema) {
    let schema = mediaObj.schema;
    if (schema.$ref) {
      schema = resolveLocalRef(doc, schema.$ref) || schema;
    }
    const sample = synthesizeJsonFromSchema(doc, schema);
    if (sample !== null) {
      return {
        body: JSON.stringify(sample, null, 2),
        contentType: jsonType
      };
    }
  }

  return { body: '', contentType: jsonType };
}

/**
 * Extracts and formats parameters (query, header, path).
 * 
 * @param {object} doc 
 * @param {Array} rawParams 
 */
function processParameters(doc, rawParams = []) {
  const queryParams = [];
  const headerParams = [];
  const pathParams = [];

  for (let param of rawParams) {
    if (!param || typeof param !== 'object') continue;

    // Resolve parameter $ref
    if (param.$ref) {
      param = resolveLocalRef(doc, param.$ref) || param;
    }

    if (!param.name) continue;

    const paramObj = {
      name: param.name,
      required: Boolean(param.required),
      description: param.description || '',
      example: param.example !== undefined ? String(param.example) : (param.schema?.default !== undefined ? String(param.schema.default) : '')
    };

    if (param.in === 'query') {
      queryParams.push(paramObj);
    } else if (param.in === 'header') {
      headerParams.push(paramObj);
    } else if (param.in === 'path') {
      pathParams.push(paramObj);
    }
  }

  return { queryParams, headerParams, pathParams };
}

/**
 * Main parser entry point. Parses an OpenAPI 3.x specification and returns structured API details and endpoint list.
 * 
 * @param {object} doc 
 * @returns {{ apiInfo: object, servers: string[], endpoints: object[] }}
 */
function parseOpenApi(doc, documentSourceUrl = null) {
  validateOpenApiDocument(doc);

  const apiInfo = {
    title: doc.info?.title || 'Spring Boot API',
    version: doc.info?.version || '1.0.0',
    description: doc.info?.description || '',
    openApiVersion: doc.openapi
  };

  // Determine origin from document source URL if provided (remote or local network)
  let documentOrigin = null;
  if (documentSourceUrl && typeof documentSourceUrl === 'string') {
    try {
      const parsedDocUrl = new URL(documentSourceUrl.trim());
      documentOrigin = parsedDocUrl.origin;
    } catch (_) {}
  }

  // Extract server URLs with RFC/OpenAPI 3.x relative URL resolution
  const servers = [];
  if (Array.isArray(doc.servers) && doc.servers.length > 0) {
    for (const server of doc.servers) {
      if (server && server.url) {
        let rawUrl = String(server.url).trim();
        let resolvedUrl = rawUrl;

        // If the server URL is relative (e.g. "/", "/api/v1", "./") and we know the document source URL,
        // resolve it against documentSourceUrl according to OpenAPI specification rules
        if (documentSourceUrl && !rawUrl.startsWith('http://') && !rawUrl.startsWith('https://')) {
          try {
            const resolved = new URL(rawUrl, documentSourceUrl);
            resolvedUrl = resolved.href.replace(/\/+$/, '');
          } catch (_) {
            resolvedUrl = rawUrl.replace(/\/+$/, '');
          }
        } else {
          resolvedUrl = rawUrl.replace(/\/+$/, '');
        }

        if (resolvedUrl && !servers.includes(resolvedUrl)) {
          servers.push(resolvedUrl);
        }
      }
    }
  }

  // If no servers or only empty entries specified in OpenAPI document:
  // OpenAPI 3.x specification defines default server URL as "/" relative to document location
  if (servers.length === 0) {
    if (documentOrigin) {
      servers.push(documentOrigin);
    } else {
      servers.push('http://localhost:8080');
    }
  }

  const primaryServerUrl = servers[0] || 'http://localhost:8080';

  const endpoints = [];

  for (const [pathKey, pathItem] of Object.entries(doc.paths || {})) {
    if (!pathItem || typeof pathItem !== 'object') continue;

    // Path-level parameters
    const pathLevelParams = Array.isArray(pathItem.parameters) ? pathItem.parameters : [];

    for (const methodKey of SUPPORTED_HTTP_METHODS) {
      const operation = pathItem[methodKey];
      if (!operation || typeof operation !== 'object') continue;

      const upperMethod = methodKey.toUpperCase();
      const operationLevelParams = Array.isArray(operation.parameters) ? operation.parameters : [];
      const combinedParams = [...pathLevelParams, ...operationLevelParams];

      const { queryParams, headerParams, pathParams } = processParameters(doc, combinedParams);

      let bodyData = { body: '', contentType: 'application/json' };
      if (['POST', 'PUT', 'PATCH', 'DELETE'].includes(upperMethod) && operation.requestBody) {
        bodyData = extractRequestBody(doc, operation.requestBody);
      }

      const summary = operation.summary || operation.operationId || `${upperMethod} ${pathKey}`;
      const endpointId = operation.operationId || `op_${upperMethod.toLowerCase()}_${pathKey.replace(/[^a-zA-Z0-9]/g, '_')}`;

      endpoints.push({
        id: endpointId,
        method: upperMethod,
        path: pathKey,
        summary,
        description: operation.description || '',
        operationId: operation.operationId || '',
        tags: Array.isArray(operation.tags) ? operation.tags : [],
        serverUrl: primaryServerUrl,
        pathParams,
        queryParams,
        headerParams,
        body: bodyData.body,
        contentType: bodyData.contentType
      });
    }
  }

  return {
    apiInfo,
    servers,
    endpoints
  };
}

/**
 * Converts a parsed endpoint into an ApiForge Lite request object.
 * 
 * @param {object} endpoint 
 * @param {object} options 
 * @param {boolean} options.useBaseUrlVariable 
 * @param {string} options.serverUrl 
 * @returns {object} ApiForge request model
 */
function convertEndpointToRequest(endpoint, options = {}) {
  const useBaseUrl = options.useBaseUrlVariable !== false;
  const serverUrl = (options.serverUrl || endpoint.serverUrl || 'http://localhost:8080').replace(/\/+$/, '');

  let url = '';
  if (useBaseUrl) {
    // Avoid double slashes if path starts with '/'
    url = '{{baseUrl}}' + (endpoint.path.startsWith('/') ? endpoint.path : '/' + endpoint.path);
  } else {
    url = serverUrl + (endpoint.path.startsWith('/') ? endpoint.path : '/' + endpoint.path);
  }

  // Query parameters
  const params = (endpoint.queryParams || []).map(p => ({
    key: p.name,
    value: p.example || '',
    enabled: true
  }));

  // Headers
  const headers = (endpoint.headerParams || []).map(h => ({
    key: h.name,
    value: h.example || '',
    enabled: true
  }));

  // If there is a request body, ensure Content-Type is present
  if (endpoint.body && endpoint.body.trim()) {
    const hasContentType = headers.some(h => h.key.toLowerCase() === 'content-type');
    if (!hasContentType) {
      headers.unshift({
        key: 'Content-Type',
        value: endpoint.contentType || 'application/json',
        enabled: true
      });
    }
  }

  return {
    name: endpoint.summary || `${endpoint.method} ${endpoint.path}`,
    method: endpoint.method,
    url,
    params: params.length > 0 ? params : [{ key: '', value: '', enabled: true }],
    headers: headers.length > 0 ? headers : [{ key: '', value: '', enabled: true }],
    body: endpoint.body || '',
    tests: []
  };
}

module.exports = {
  SUPPORTED_HTTP_METHODS,
  MAX_DOC_SIZE_BYTES,
  validateOpenApiDocument,
  resolveLocalRef,
  synthesizeJsonFromSchema,
  extractRequestBody,
  processParameters,
  parseOpenApi,
  convertEndpointToRequest
};
